export const RepositoryClaimCommandSchema = S.Union(
  [
    S.Struct({
      command: S.Literal("create_packet"),
      packetRef: WorkPacketRefSchema,
      workRef: WorkRefSchema,
      repositoryRef: RepositoryRefSchema,
      title: ShortTextSchema,
      scope: LongTextSchema,
      ownedPaths: S.Array(ShortTextSchema).check(S.isMaxLength(256)),
      hotFiles: S.Array(ShortTextSchema).check(S.isMaxLength(256)),
      hotContracts: S.Array(ShortTextSchema).check(S.isMaxLength(256)),
      verification: LongTextSchema,
    }).annotate({ identifier: "RepositoryClaimCommandCreatePacket" }),
    S.Struct({
      command: S.Literal("claim_packet"),
      packetRef: WorkPacketRefSchema,
      claimRef: RepositoryWorkClaimRefSchema,
    }).annotate({ identifier: "RepositoryClaimCommandClaimPacket" }),
    S.Struct({
      command: S.Literal("heartbeat"),
      claimRef: RepositoryWorkClaimRefSchema,
      expectedGeneration: SafeIntegerSchema,
      evidenceRefs: S.Array(EvidenceRefSchema).check(S.isMinLength(1), S.isMaxLength(512)),
    }).annotate({ identifier: "RepositoryClaimCommandHeartbeat" }),
    S.Struct({
      command: S.Literal("status"),
      claimRef: RepositoryWorkClaimRefSchema,
      expectedGeneration: SafeIntegerSchema,
      detail: ShortTextSchema,
      evidenceRefs: S.Array(EvidenceRefSchema).check(S.isMinLength(1), S.isMaxLength(512)),
    }).annotate({ identifier: "RepositoryClaimCommandStatus" }),
    S.Struct({
      command: S.Literal("block"),
      claimRef: RepositoryWorkClaimRefSchema,
      expectedGeneration: SafeIntegerSchema,
      detail: ShortTextSchema,
      evidenceRefs: S.Array(EvidenceRefSchema).check(S.isMinLength(1), S.isMaxLength(512)),
    }).annotate({ identifier: "RepositoryClaimCommandBlock" }),
    S.Struct({
      command: S.Literal("release"),
      claimRef: RepositoryWorkClaimRefSchema,
      expectedGeneration: SafeIntegerSchema,
      evidenceRefs: S.Array(EvidenceRefSchema).check(S.isMinLength(1), S.isMaxLength(512)),
    }).annotate({ identifier: "RepositoryClaimCommandRelease" }),
    S.Struct({
      command: S.Literal("takeover"),
      claimRef: RepositoryWorkClaimRefSchema,
      expectedGeneration: SafeIntegerSchema,
      auditRef: EvidenceRefSchema,
      auditFoundActiveWork: S.Boolean,
      auditedAt: IsoTimestampSchema,
    }).annotate({ identifier: "RepositoryClaimCommandTakeover" }),
  ],
  { mode: "oneOf" },
).annotate({ identifier: "RepositoryClaimCommand" });
export type RepositoryClaimCommand = typeof RepositoryClaimCommandSchema.Type;

